.trm{--ink:#2f2b26;--muted:#7a7064;--paper:#fbf7ef;--line:#e8dfcd;font-family:-apple-system,BlinkMacSystemFont,"PingFang SC","Hiragino Sans GB","Segoe UI",sans-serif;color:var(--ink);background:var(--paper);border:1px solid var(--line);border-radius:16px;padding:12px 14px 14px;font-variant-numeric:tabular-nums}
.trm *{box-sizing:border-box}
.trm-tabs{display:grid;grid-template-columns:0.8fr repeat(5,1fr);gap:6px}
.trm-tab{all:unset;cursor:pointer;position:relative;display:flex;flex-direction:column;gap:2px;padding:9px 10px 8px;border-radius:10px;background:#fff;border:1px solid var(--line);min-width:0;transition:background .2s,border-color .2s,transform .2s}
.trm-tab::before{content:"";position:absolute;left:10px;right:10px;top:-1px;height:4px;border-radius:0 0 3px 3px;background:var(--tc);opacity:.85}
.trm-tab.is-all::before{background:repeating-linear-gradient(90deg,#cf4a2c 0 20%,#7d5ba6 20% 40%,#4f8a3c 40% 60%,#2f7f8f 60% 80%,#b7832a 80% 100%)}
.trm-tab:hover{border-color:color-mix(in srgb,var(--tc) 45%,var(--line))}
.trm-tab.is-on{background:color-mix(in srgb,var(--tc) 11%,#fff);border-color:color-mix(in srgb,var(--tc) 60%,#fff);transform:translateY(-1px)}
.trm-tab:focus-visible{outline:2px solid var(--tc);outline-offset:2px}
.trm-tab-k{font-size:11.5px;letter-spacing:.04em;color:var(--tc);font-weight:650;text-transform:uppercase}
.trm-tab-t{font-family:"Songti SC","STSong","Noto Serif CJK SC","Source Han Serif SC",Georgia,serif;font-size:14px;font-weight:600;line-height:1.25;color:var(--ink);overflow:hidden;text-overflow:ellipsis;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical}
.trm-body{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.18fr);gap:16px;margin-top:12px;align-items:start}
.trm-side{min-width:0}
.trm-hint{margin:2px 0 8px;font-size:12.5px;color:var(--muted)}
.trm-days{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:6px}
.trm-dayrow{all:unset;cursor:pointer;display:flex;gap:10px;align-items:flex-start;width:100%;padding:8px 10px;border-radius:10px;background:#fff;border:1px solid var(--line);transition:border-color .15s,background .15s}
.trm-dayrow:hover,.trm-dayrow:focus-visible{border-color:var(--tc);background:color-mix(in srgb,var(--tc) 7%,#fff)}
.trm-dot{flex:none;width:10px;height:10px;border-radius:50%;background:var(--tc);margin-top:5px}
.trm-dayrow-main{display:flex;flex-direction:column;gap:1px;min-width:0;flex:1}
.trm-dayrow-h{display:flex;align-items:baseline;gap:8px;min-width:0}
.trm-dayrow-k{flex:none;font-size:11px;color:var(--tc);font-weight:650;letter-spacing:.04em;text-transform:uppercase}
.trm-dayrow b{font-family:"Songti SC","STSong","Noto Serif CJK SC",Georgia,serif;font-size:15px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.trm-route{font-size:12px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.trm-dayrow-n{flex:none;font-size:12px;color:var(--muted);margin-top:2px}
.trm-summary{margin:0 0 8px;font-family:"Songti SC","STSong","Noto Serif CJK SC",Georgia,serif;font-size:15px;line-height:1.5;color:var(--ink);border-left:3px solid var(--c);padding-left:10px;animation:trm-in .35s ease}
.trm-stops{list-style:none;margin:0;padding:0;animation:trm-in .35s ease}
@keyframes trm-in{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:none}}
.trm-leg{display:flex;align-items:center;gap:6px;margin:0 0 0 13px;padding:3px 0 3px 18px;border-left:2px dotted color-mix(in srgb,var(--c) 55%,#fff);font-size:11.5px;color:var(--muted);white-space:nowrap;overflow:hidden}
.trm-leg.is-train,.trm-leg.is-bus{border-left-style:solid}
.trm-leg-m{flex:none;font-size:10.5px;padding:1px 6px;border-radius:999px;background:#efe7d8;color:#5c5246;font-weight:600}
.trm-leg.is-train .trm-leg-m,.trm-leg.is-bus .trm-leg-m{background:color-mix(in srgb,var(--c) 16%,#fff);color:color-mix(in srgb,var(--c) 80%,#000)}
.trm-leg-t{overflow:hidden;text-overflow:ellipsis}
.trm-stop{all:unset;cursor:pointer;display:flex;gap:10px;align-items:flex-start;width:100%;padding:6px 8px 6px 2px;border-radius:9px;transition:background .15s}
.trm-stop:hover,.is-active .trm-stop{background:color-mix(in srgb,var(--c) 9%,transparent)}
.trm-stop:focus-visible{outline:2px solid var(--c)}
.trm-num{flex:none;width:24px;height:24px;border-radius:50%;display:grid;place-items:center;font-size:12px;font-weight:700;color:var(--c);background:#fff;border:2px solid var(--c)}
.is-active .trm-num{background:var(--c);color:#fff}
.trm-stop-main{display:flex;flex-direction:column;gap:3px;min-width:0;flex:1;padding-top:2px}
.trm-stop-head{display:flex;align-items:baseline;gap:8px;min-width:0}
.trm-stop-head b{font-size:14.5px;font-weight:650;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.trm-area{font-size:11.5px;color:var(--muted);white-space:nowrap}
.trm-stop-head time{margin-left:auto;font-size:12px;color:var(--muted);flex:none}
.trm-note{font-size:12.5px;line-height:1.5;color:#4d453b;animation:trm-in .25s ease}
.trm-totals{display:flex;flex-wrap:wrap;gap:4px 14px;align-items:center;margin:10px 0 0;padding-top:9px;border-top:1px dashed var(--line);font-size:12.5px;color:#4d453b}
.trm-totals i{display:inline-block;width:18px;height:0;margin-right:6px;vertical-align:middle;border-top:2.5px dotted var(--c)}
.trm-totals i.is-ride{border-top-style:solid}
.trm-totals-hint{color:var(--muted);font-size:12px}
.trm-map{margin:0;min-width:0}
.trm-map svg{display:block;width:100%;height:auto;aspect-ratio:460/340;border-radius:12px;border:1px solid var(--line);background:#f7f1e5}
.trm-map figcaption{margin-top:6px;font-size:11.5px;color:var(--muted);text-align:right}
.trm-dn{font-family:"Songti SC","STSong",Georgia,serif;font-size:11px;fill:#9b8f7c;letter-spacing:.08em}
.trm-ds{font-size:7.5px;fill:#b2a690;letter-spacing:.14em;text-transform:uppercase}
.trm-inset-t{font-size:10px;fill:#8a7a5c;font-weight:600}
.trm-base-t{font-size:10px;fill:#3d3a35;font-weight:600;paint-order:stroke;stroke:#f7f1e5;stroke-width:3px}
.trm-pin{cursor:pointer}
.trm-pin-n{font-size:11px;font-weight:700;pointer-events:none}
.trm-pulse{animation:trm-pulse 1.8s ease-out infinite;transform-origin:center}
@keyframes trm-pulse{0%{transform:scale(.7);opacity:.35}100%{transform:scale(1.5);opacity:0}}
.trm-label text{font-size:12px;font-weight:600}
.trm-mini{cursor:pointer}
.trm-badge{cursor:pointer}
.trm-badge text{font-size:10.5px;font-weight:700;fill:#fff;pointer-events:none}
.trm-scale text,.trm-north text{font-size:9px;fill:#7a7064}
@media (prefers-reduced-motion:reduce){.trm-pulse,.trm-stops,.trm-summary,.trm-note{animation:none}}
@media (max-width:760px){.trm-tabs{grid-template-columns:repeat(3,1fr)}.trm-body{grid-template-columns:1fr}.trm-map{order:-1}}
@media (max-width:420px){.trm{padding:10px}.trm-tabs{grid-template-columns:repeat(2,1fr)}.trm-area{display:none}}
