.tb{--ink:#2f2b26;--muted:#7a7064;--line:#e8dfcd;display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,1fr);gap:18px;padding:16px;border:1px solid var(--line);border-radius:16px;background:#fbf7ef;color:var(--ink);font-family:-apple-system,BlinkMacSystemFont,"PingFang SC","Hiragino Sans GB","Segoe UI",sans-serif;font-variant-numeric:tabular-nums}
.tb *{box-sizing:border-box}
.tb-controls{display:flex;flex-direction:column;gap:14px;min-width:0}
.tb-row{display:grid;grid-template-columns:72px 1fr auto;align-items:center;gap:12px}
.tb-label{font-size:12px;color:var(--muted);letter-spacing:.04em}
.tb-aside{font-size:12.5px;color:var(--muted);white-space:nowrap}
.tb-strong{color:var(--ink);font-weight:650;font-size:14px;min-width:44px;text-align:right}
.tb-stepper{display:inline-flex;align-items:center;gap:0;justify-self:start;border:1px solid var(--line);border-radius:999px;background:#fff;overflow:hidden}
.tb-stepper button{all:unset;cursor:pointer;width:34px;height:32px;display:grid;place-items:center;font-size:18px;color:#5c5246}
.tb-stepper button:hover{background:#f3ece0}
.tb-stepper button:disabled{opacity:.3;cursor:default}
.tb-stepper output{min-width:56px;text-align:center;font-weight:650;font-size:14px}
.tb input[type=range]{-webkit-appearance:none;appearance:none;width:100%;height:6px;border-radius:999px;background:linear-gradient(90deg,#c0672f var(--p),#eadfcb var(--p));outline:none}
.tb input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:20px;height:20px;border-radius:50%;background:#fff;border:2px solid #c0672f;box-shadow:0 1px 3px rgba(0,0,0,.15);cursor:pointer}
.tb input[type=range]::-moz-range-thumb{width:18px;height:18px;border-radius:50%;background:#fff;border:2px solid #c0672f;cursor:pointer}
.tb-hotel{display:flex;flex-direction:column;gap:8px}
.tb-tiers{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}
.tb-tier{all:unset;cursor:pointer;display:flex;flex-direction:column;gap:3px;padding:10px 11px;border-radius:11px;background:#fff;border:1.5px solid var(--line);transition:border-color .15s,background .15s;min-width:0}
.tb-tier:hover{border-color:#d9b998}
.tb-tier.is-on{border-color:#c0672f;background:#fdf1e6}
.tb-tier:focus-visible{outline:2px solid #c0672f;outline-offset:2px}
.tb-tier b{font-size:14px}
.tb-tier span{font-size:11.5px;color:var(--muted);line-height:1.4}
.tb-tier em{font-style:normal;font-size:12px;color:#8b5a2b;font-weight:600;margin-top:2px}
.tb-delta{margin:2px 0 0;font-size:12.5px;color:#8b5a2b;background:#fdf1e6;border-radius:8px;padding:7px 10px}
.tb-result{display:flex;flex-direction:column;gap:6px;padding:14px 16px;border-radius:12px;background:#fff;border:1px dashed #d9c9ab;min-width:0}
.tb-total{font-family:"Songti SC","STSong","Noto Serif CJK SC",Georgia,serif;font-size:34px;line-height:1.1;font-weight:700;color:#8b3f1d;transition:color .2s}
.tb-sub{display:flex;flex-wrap:wrap;gap:4px 16px;font-size:12.5px;color:var(--muted)}
.tb-sub b{color:var(--ink);font-weight:650}
.tb-bar{display:flex;height:12px;border-radius:999px;overflow:hidden;margin:6px 0 2px;background:#f0e8da}
.tb-bar span{height:100%;transition:width .35s ease}
.tb-parts{list-style:none;margin:2px 0 0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:4px 14px}
.tb-parts li{display:flex;align-items:center;gap:7px;font-size:12.5px;min-width:0}
.tb-parts i{flex:none;width:9px;height:9px;border-radius:3px}
.tb-parts span{color:#4d453b;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tb-parts b{margin-left:auto;font-weight:600}
.tb-note{margin:6px 0 0;font-size:11.5px;color:var(--muted);line-height:1.45}
